class StockSpanner:

    def __init__(self):
        self.stock = []
        self.stack = []

    def next(self, price: int) -> int:
        self.stock.append(price)

        while self.stack and self.stock[self.stack[-1]] <= price:
            self.stack.pop()

        span = len(self.stock)
        if self.stack:
            span -= self.stack[-1] + 1

        self.stack.append(len(self.stock) - 1)
        return span


